     1	package com.marealta.mail;
     2	
     3	/** Blocks messages to malformed addresses so the front desk can call the guest. */
     4	public final class AddressValidation implements Outbox {
     5	    private final Outbox next;
     6	
     7	    public AddressValidation(Outbox next) {
     8	        this.next = next;
     9	    }
    10	
    11	    @Override
    12	    public Message send(Message message) {
    13	        return isValid(message.to()) ? next.send(message) : next.send(message.blocked());
    14	    }
    15	
    16	    static boolean isValid(String address) {
    17	        if (address == null) {
    18	            return false;
    19	        }
    20	        int at = address.indexOf('@');
    21	        if (at <= 0 || at != address.lastIndexOf('@')) {
    22	            return false;
    23	        }
    24	        String domain = address.substring(at + 1);
    25	        for (int i = 1; i < domain.length() - 1; i++) {
    26	            if (domain.charAt(i) == '.') {
    27	                return true;
    28	            }
    29	        }
    30	        return false;
    31	    }
    32	}
