     3	/** After a message is sent, sends a copy of it to the accountant's archive. */
     4	public final class ArchiveCopy implements Outbox {
     5	    private final Outbox next;
     6	    private final String archiveAddress;
     7	
     8	    public ArchiveCopy(Outbox next, String archiveAddress) {
     9	        this.next = next;
    10	        this.archiveAddress = archiveAddress;
    11	    }
    12	
    13	    @Override
    14	    public Message send(Message message) {
    15	        Message recorded = next.send(message);
    16	        if (recorded.status() == MessageStatus.SENT) {
    17	            next.send(Message.email(archiveAddress, "[Cópia] " + message.subject(), message.body()));
    18	        }
    19	        return recorded;
    20	    }
