     1	package com.marealta.mail;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.function.UnaryOperator;
     6	
     7	/**
     8	 * The one place that decides which rules wrap the outbox for this installation.
     9	 * Rules are listed from the outermost to the innermost; a new rule is one class and one line here.
    10	 */
    11	public final class MailPipeline {
    12	    private enum Scope {
    13	        ALWAYS, TEST_ONLY, LIVE_ONLY;
    14	
    15	        boolean applies(boolean testMode) {
    16	            return this == ALWAYS || (this == TEST_ONLY) == testMode;
    17	        }
    18	    }
    19	
    20	    private record Rule(Scope scope, UnaryOperator<Outbox> wrap) {
    21	    }
    22	
    23	    private MailPipeline() {
    24	    }
    25	
    26	    public static Outbox build(Outbox log, MailSettings settings) {
    27	        List<Rule> rules = new ArrayList<>();
    28	        rules.add(new Rule(Scope.ALWAYS, Serialized::new));
    29	        rules.add(new Rule(Scope.ALWAYS, AddressValidation::new));
    30	        if (settings.archiveCopy()) {
    31	            rules.add(new Rule(Scope.LIVE_ONLY, next -> new ArchiveCopy(next, MailSettings.ARCHIVE_ADDRESS)));
    32	        }
    33	        rules.add(new Rule(Scope.TEST_ONLY, next -> new TestRedirect(next, MailSettings.TEST_ADDRESS)));
    34	
    35	        Outbox outbox = log;
    36	        for (int i = rules.size() - 1; i >= 0; i--) {
    37	            Rule rule = rules.get(i);
    38	            if (rule.scope().applies(settings.testMode())) {
    39	                outbox = rule.wrap().apply(outbox);
    40	            }
    41	        }
    42	        return outbox;
    43	    }
    44	}
