     3	/** Sends everything to a test mailbox instead of the real recipient. */
     4	public final class TestRedirect implements Outbox {
     5	    private final Outbox next;
     6	    private final String testAddress;
     7	
     8	    public TestRedirect(Outbox next, String testAddress) {
     9	        this.next = next;
    10	        this.testAddress = testAddress;
    11	    }
    12	
    13	    @Override
    14	    public Message send(Message message) {
    15	        if (message.status() == MessageStatus.BLOCKED) {
    16	            return next.send(message);
    17	        }
    18	        return next.send(message.redirectedTo(testAddress,
    19	                "[TESTE] " + message.subject(),
    20	                "Destinatário original: " + message.to() + "\n" + message.body()));
    21	    }
    22	}
