     5	
     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	
    10	public final class Database {
    11	    @FunctionalInterface
    12	    public interface Work<T> {
    13	        T run(Connection connection) throws SQLException;
    14	    }
    15	
    16	    private final HikariDataSource dataSource;
    17	
    18	    public Database(String url, String user, String password) {
    19	        HikariConfig config = new HikariConfig();
    20	        config.setJdbcUrl(url);
    21	        config.setUsername(user);
    22	        config.setPassword(password);
    23	        config.setMaximumPoolSize(10);
    24	        config.setInitializationFailTimeout(60_000);
    25	        this.dataSource = new HikariDataSource(config);
    26	    }
    27	
    28	    public <T> T transaction(Work<T> work) {
    29	        try (Connection connection = dataSource.getConnection()) {
    30	            connection.setAutoCommit(false);
    31	            try {
    32	                T result = work.run(connection);
    33	                connection.commit();
    34	                return result;
    35	            } catch (SQLException | RuntimeException e) {
    36	                connection.rollback();
    37	                throw e;
    38	            }
    39	        } catch (SQLException e) {
    40	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
    41	        }
    42	    }
    43	
    44	    public void migrate() {
    45	        transaction(c -> {
    46	            try (Statement s = c.createStatement()) {
    47	                s.execute("SELECT pg_advisory_xact_lock(7070)");
    48	                s.execute("""
    49	                        CREATE TABLE IF NOT EXISTS rooms (
    50	                            number INTEGER PRIMARY KEY,
    51	                            type VARCHAR(20) NOT NULL,
    52	                            capacity INTEGER NOT NULL,
    53	                            nightly_rate NUMERIC(12,2) NOT NULL
    54	                        )""");
    55	                s.execute("""
    56	                        CREATE TABLE IF NOT EXISTS reservations (
    57	                            id BIGSERIAL PRIMARY KEY,
    58	                            room_number INTEGER NOT NULL REFERENCES rooms(number),
    59	                            guest_name TEXT NOT NULL,
    60	                            guest_email TEXT NOT NULL,
    61	                            guest_cpf TEXT NOT NULL,
    62	                            check_in DATE NOT NULL,
    63	                            check_out DATE NOT NULL,
    64	                            guests INTEGER NOT NULL,
    65	                            rate_plan VARCHAR(20) NOT NULL,
    66	                            nights INTEGER NOT NULL,
    67	                            subtotal NUMERIC(12,2) NOT NULL,
    68	                            discount NUMERIC(12,2) NOT NULL,
    69	                            total NUMERIC(12,2) NOT NULL,
    70	                            status VARCHAR(20) NOT NULL,
    71	                            amount_paid NUMERIC(12,2) NOT NULL,
    72	                            refund NUMERIC(12,2)
    73	                        )""");
    74	                s.execute("""
    75	                        CREATE TABLE IF NOT EXISTS messages (
    76	                            id BIGSERIAL PRIMARY KEY,
    77	                            channel VARCHAR(20) NOT NULL,
    78	                            recipient TEXT NOT NULL,
    79	                            subject TEXT NOT NULL,
    80	                            body TEXT NOT NULL,
    81	                            status VARCHAR(20) NOT NULL
    82	                        )""");
    83	                s.execute("""
    84	                        INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    85	                            (101, 'STANDARD', 2, 249.90),
    86	                            (102, 'STANDARD', 2, 249.90),
    87	                            (201, 'DELUXE', 3, 389.90),
    88	                            (202, 'DELUXE', 3, 389.90),
    89	                            (301, 'SUITE', 4, 579.90)
    90	                        ON CONFLICT (number) DO NOTHING""");
    91	            }
    92	            return null;
    93	        });
    94	    }
    95	}
