     8	import java.sql.PreparedStatement;
     9	import java.sql.ResultSet;
    10	import java.sql.SQLException;
    11	import java.sql.Statement;
    12	import java.util.ArrayList;
    13	import java.util.List;
    14	
    15	/** The list of sent messages. Emails do not leave the system yet: this is the innermost Outbox. */
    16	public final class MessageLog implements Outbox {
    17	    private final Database database;
    18	
    19	    public MessageLog(Database database) {
    20	        this.database = database;
    21	    }
    22	
    23	    @Override
    24	    public Message send(Message message) {
    25	        return database.transaction(c -> {
    26	            try (PreparedStatement ps = c.prepareStatement(
    27	                    "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?,?,?,?,?)",
    28	                    Statement.RETURN_GENERATED_KEYS)) {
    29	                ps.setString(1, message.channel().name());
    30	                ps.setString(2, message.to());
    31	                ps.setString(3, message.subject());
    32	                ps.setString(4, message.body());
    33	                ps.setString(5, message.status().name());
    34	                ps.executeUpdate();
    35	                try (ResultSet keys = ps.getGeneratedKeys()) {
    36	                    keys.next();
    37	                    return message.withId(keys.getLong("id"));
    38	                }
    39	            }
    40	        });
    41	    }
    42	
    43	    public List<Message> all() {
    44	        return database.transaction(c -> {
    45	            try (PreparedStatement ps = c.prepareStatement(
    46	                    "SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id");
    47	                 ResultSet rs = ps.executeQuery()) {
    48	                List<Message> list = new ArrayList<>();
    49	                while (rs.next()) {
    50	                    list.add(new Message(rs.getLong("id"), Channel.valueOf(rs.getString("channel")),
    51	                            rs.getString("recipient"), rs.getString("subject"), rs.getString("body"),
    52	                            MessageStatus.valueOf(rs.getString("status"))));
    53	                }
    54	                return list;
    55	            }
    56	        });
    57	    }
    58	}
