    21	public final class ReservationRepository {
    22	    private static final String SELECT = """
    23	            SELECT r.*, m.type AS room_type, m.capacity, m.nightly_rate
    24	            FROM reservations r JOIN rooms m ON m.number = r.room_number
    25	            """;
    26	
    27	    public boolean isRoomTaken(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    28	            throws SQLException {
    29	        try (PreparedStatement ps = c.prepareStatement("""
    30	                SELECT 1 FROM reservations
    31	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?""")) {
    32	            ps.setInt(1, roomNumber);
    33	            ps.setDate(2, Date.valueOf(checkOut));
    34	            ps.setDate(3, Date.valueOf(checkIn));
    35	            try (ResultSet rs = ps.executeQuery()) {
    36	                return rs.next();
    37	            }
    38	        }
    39	    }
    40	
    41	    public void insert(Connection c, Reservation r) throws SQLException {
    42	        try (PreparedStatement ps = c.prepareStatement("""
    43	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    44	                    guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    45	                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", Statement.RETURN_GENERATED_KEYS)) {
    46	            ps.setInt(1, r.room().number());
    47	            ps.setString(2, r.guestName());
    48	            ps.setString(3, r.guestEmail());
    49	            ps.setString(4, r.guestCpf());
    50	            ps.setDate(5, Date.valueOf(r.checkInDate()));
    51	            ps.setDate(6, Date.valueOf(r.checkOutDate()));
    52	            ps.setInt(7, r.guests());
    53	            ps.setString(8, r.ratePlan().name());
    54	            ps.setInt(9, r.quote().nights());
    55	            ps.setBigDecimal(10, r.quote().subtotal());
    56	            ps.setBigDecimal(11, r.quote().discount());
    57	            ps.setBigDecimal(12, r.quote().total());
    58	            ps.setString(13, r.status().name());
    59	            ps.setBigDecimal(14, r.amountPaid());
    60	            ps.setBigDecimal(15, r.refund());
    61	            ps.executeUpdate();
    62	            try (ResultSet keys = ps.getGeneratedKeys()) {
    63	                keys.next();
    64	                r.assignId(keys.getLong("id"));
    65	            }
    66	        }
    67	    }
    68	
    69	    public void update(Connection c, Reservation r) throws SQLException {
    70	        try (PreparedStatement ps = c.prepareStatement(
    71	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    72	            ps.setString(1, r.status().name());
    73	            ps.setBigDecimal(2, r.amountPaid());
    74	            ps.setBigDecimal(3, r.refund());
    75	            ps.setLong(4, r.id());
    76	            ps.executeUpdate();
    77	        }
    78	    }
    79	
    80	    public Optional<Reservation> find(Connection c, long id, boolean lock) throws SQLException {
    81	        try (PreparedStatement ps = c.prepareStatement(
    82	                SELECT + "WHERE r.id = ?" + (lock ? " FOR UPDATE OF r" : ""))) {
    83	            ps.setLong(1, id);
    84	            try (ResultSet rs = ps.executeQuery()) {
    85	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
    86	            }
    87	        }
    88	    }
    89	
    90	    public List<Reservation> findPaidOccupying(Connection c, LocalDate night) throws SQLException {
    91	        return query(c, "WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
    92	                + "AND r.check_in <= ? AND r.check_out > ? ORDER BY r.room_number, r.id", night, night);
    93	    }
    94	
    95	    public List<Reservation> findRetainingMoneyStartingBetween(Connection c, LocalDate from, LocalDate toExclusive)
    96	            throws SQLException {
    97	        return query(c, "WHERE r.check_in >= ? AND r.check_in < ? "
    98	                + "AND r.amount_paid - COALESCE(r.refund, 0) > 0 ORDER BY r.check_in, r.id", from, toExclusive);
    99	    }
   100	
   101	    private List<Reservation> query(Connection c, String where, LocalDate a, LocalDate b) throws SQLException {
   102	        try (PreparedStatement ps = c.prepareStatement(SELECT + where)) {
   103	            ps.setDate(1, Date.valueOf(a));
   104	            ps.setDate(2, Date.valueOf(b));
   105	            try (ResultSet rs = ps.executeQuery()) {
   106	                List<Reservation> list = new ArrayList<>();
   107	                while (rs.next()) {
   108	                    list.add(map(rs));
   109	                }
   110	                return list;
   111	            }
   112	        }
   113	    }
   114	
   115	    private static Reservation map(ResultSet rs) throws SQLException {
   116	        Room room = new Room(rs.getInt("room_number"), RoomType.valueOf(rs.getString("room_type")),
   117	                rs.getInt("capacity"), rs.getBigDecimal("nightly_rate"));
   118	        Pricing.Quote quote = new Pricing.Quote(rs.getInt("nights"), rs.getBigDecimal("subtotal"),
   119	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"));
   120	        return new Reservation(rs.getLong("id"), room, rs.getString("guest_name"), rs.getString("guest_email"),
   121	                rs.getString("guest_cpf"), rs.getDate("check_in").toLocalDate(),
   122	                rs.getDate("check_out").toLocalDate(), rs.getInt("guests"),
   123	                RatePlan.valueOf(rs.getString("rate_plan")), quote,
   124	                ReservationStatus.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"),
   125	                rs.getBigDecimal("refund"));
   126	    }
   127	}
