    14	
    15	public final class Reports {
    16	    private final Database database;
    17	    private final RoomRepository rooms;
    18	    private final ReservationRepository reservations;
    19	
    20	    public Reports(Database database, RoomRepository rooms, ReservationRepository reservations) {
    21	        this.database = database;
    22	        this.rooms = rooms;
    23	        this.reservations = reservations;
    24	    }
    25	
    26	    public String occupancy(LocalDate night) {
    27	        return database.transaction(c -> {
    28	            List<Reservation> occupying = reservations.findPaidOccupying(c, night);
    29	            int totalRooms = rooms.all(c).size();
    30	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    31	            for (Reservation r : occupying) {
    32	                Room room = r.room();
    33	                csv.append(room.number()).append(',').append(room.type()).append(',').append(r.id()).append(',')
    34	                        .append(r.checkInDate()).append(',').append(r.checkOutDate()).append('\n');
    35	            }
    36	            long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    37	            return csv.append("total,").append(occupiedRooms).append('/').append(totalRooms).append('\n')
    38	                    .toString();
    39	        });
    40	    }
    41	
    42	    public String revenue(YearMonth month) {
    43	        return database.transaction(c -> {
    44	            List<Reservation> starting = reservations.findRetainingMoneyStartingBetween(
    45	                    c, month.atDay(1), month.plusMonths(1).atDay(1));
    46	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    47	            BigDecimal sum = Money.ZERO;
    48	            for (Reservation r : starting) {
