    15	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    16	        BigDecimal subtotal = Money.ZERO;
    17	        int nights = 0;
    18	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    19	            subtotal = subtotal.add(nightPrice(room, night));
    20	            nights++;
    21	        }
    22	        BigDecimal discount = plan.discountOn(subtotal);
    23	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    24	    }
    25	
    26	    static BigDecimal nightPrice(Room room, LocalDate night) {
    27	        BigDecimal rate = room.nightlyRate();
    28	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    29	    }
